"""Golan '73 counters cut from the printed Set-up Cards (docs/games/golan73/other/*SetupCard.pdf, 300 dpi scans).

Usage: python3 -I tools/golan73/chit_scans.py
Writes web/public/golan73/chit/<counter id>.jpg: the counters the review asked to show as printed (colours, pictures and lettering
of the real counter), and web/src/golan-chit-scans.ts listing them. The crop boxes (x, y, size in px on the card turned upright)
were found once by matching each counter on the card; the cards are the source, nothing else is used.
"""
import os, subprocess, tempfile, json
from PIL import Image, ImageFilter

CARDS = {
    'IsraeliSetupCard': {'IC03': (388, 1121, 168), 'IC04': (557, 1117, 170), 'IC10': (2150, 408, 168), 'IC16': (1725, 1805, 169), 'IC18': (1390, 1802, 169), 'IC20': (1222, 1800, 170), 'IC22': (1554, 1801, 170), 'IC30': (1315, 2077, 169), 'IC36': (1214, 2345, 170), 'IC43': (1488, 2626, 167), 'IC47': (551, 2895, 170), 'M01': (1872, 735, 170)},
    'SyrianSetupCard': {'M03': (2043, 876, 170), 'SC01': (53, 1403, 169), 'SC14': (1065, 1401, 171), 'SC15': (1735, 1403, 171), 'SC16': (1567, 1404, 169), 'SC17': (222, 1404, 167), 'SC19': (52, 1211, 169), 'SC23': (671, 2077, 171), 'SC25': (998, 2364, 171), 'SC26': (830, 2366, 170), 'SC27': (661, 2363, 171), 'SC29': (1335, 2369, 169), 'SC30': (1500, 2363, 171), 'SC32': (660, 2649, 170), 'SC35': (995, 2648, 172), 'SC36': (1649, 2650, 171), 'SC37': (1817, 2650, 171), 'SC38': (1482, 2651, 169), 'SC40': (2153, 2648, 172), 'SC41': (384, 2934, 170), 'SC42': (51, 2935, 169), 'SC43': (217, 2936, 169), 'SC44': (871, 2935, 170), 'SC45': (1038, 2936, 170), 'SC46': (702, 2937, 169), 'SC48': (1345, 2935, 170)},
}
OUT = 'web/public/golan73/chit/'; os.makedirs(OUT, exist_ok=True)
done = []
for card, boxes in CARDS.items():
    with tempfile.TemporaryDirectory() as t:
        subprocess.run(['pdfimages', '-j', f'docs/games/golan73/other/{card}.pdf', f'{t}/c'], check=True)
        im = Image.open(f'{t}/c-000.jpg').convert('RGB').rotate(90, expand=True)          # the cards are scanned on their side
    for cid, (x, y, s) in boxes.items():
        c = im.crop((x, y, x + s, y + s)).resize((256, 256), Image.LANCZOS).filter(ImageFilter.UnsharpMask(radius=1.2, percent=60, threshold=2))
        c.save(f'{OUT}{cid}.jpg', quality=90, optimize=True); done.append(cid)
open('web/src/golan-chit-scans.ts', 'w').write('// generated by tools/golan73/chit_scans.py: Golan counters shown as printed (cut from the Set-up Cards)\nexport const GOLAN_SCANS = ' + json.dumps(sorted(done)) + ' as const;\n')
print(len(done), 'counters', sum(os.path.getsize(OUT + f) for f in os.listdir(OUT)) // 1024, 'KB')
